mapper.select:
/*getMasterMpSoProgessDmSendPopPoList*/ SELECT PO.BUYER AS BUYER, PO.PO_NO AS PO_NO, PO.PO_SEQ AS PO_SEQ, PO.BUYER_ITEM_NO AS BUYER_ITEM_NO, PO.DESCRIPTION AS DESCRIPTION, PO.SPECIFICATION AS SPECIFICATION, PO.ITEM_QTY AS PO_QTY, PO.UNIT_PRICE AS UNIT_PRICE, PO.ITEM_AMT AS ITEM_AMT, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = PR.REQ_USER_ID) AS REQ_USER_NAME FROM ICOMPRDT PR, ICOMPODT PO WHERE 1=1 AND PR.BUYER = PO.BUYER AND PR.PR_NO = PO.PR_NO AND PR.PR_SEQ = PO.PR_SEQ AND (PO.BUYER, PO.PO_NO, PO.PO_SEQ) IN
('${st_polist}')
ORDER BY PO.PO_NO, PO.ADD_DATE

/*getMasterMpSoProgessDmSendPopUserList*/ SELECT X.RECV_NAME, X.EMAIL, X.MOBILE FROM ( SELECT (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = PR.REQ_USER_ID) AS RECV_NAME, (SELECT EMAIL FROM ICOMLUSR WHERE USER_ID = PR.REQ_USER_ID) AS EMAIL, (SELECT MOBILE_PHONE FROM ICOMLUSR WHERE USER_ID = PR.REQ_USER_ID) AS MOBILE FROM ICOMPRDT PR, ICOMPODT PO WHERE 1=1 AND PR.BUYER = PO.BUYER AND PR.PR_NO = PO.PR_NO AND PR.PR_SEQ = PO.PR_SEQ AND (PO.BUYER, PO.PO_NO, PO.PO_SEQ) IN
('${st_polist}')
UNION ALL
SELECT (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = PR.PURCHASER_ID) AS RECV_NAME, (SELECT EMAIL FROM ICOMLUSR WHERE USER_ID = PR.PURCHASER_ID) AS EMAIL, (SELECT MOBILE_PHONE FROM ICOMLUSR WHERE USER_ID = PR.PURCHASER_ID) AS MOBILE FROM ICOMPRDT PR, ICOMPODT PO WHERE 1=1 AND PR.BUYER = PO.BUYER AND PR.PR_NO = PO.PR_NO AND PR.PR_SEQ = PO.PR_SEQ AND (PO.BUYER, PO.PO_NO, PO.PO_SEQ) IN
('${st_polist2}')
) X GROUP BY X.RECV_NAME, X.EMAIL, X.MOBILE

