INSERT INTO DM_SEND_INFO ( DM_ID, SEQ, SENT_BUYER, SENT_PO_NO, SENT_PO_SEQ
) VALUES ( #{DM_ID}, (SELECT NVL(MAX(TO_NUMBER(SEQ)),0)+1 FROM DM_SEND_INFO WHERE DM_ID = #{DM_ID}), #{BUYER}, #{PO_NO}, #{PO_SEQ} )
